#include <stdio.h>
#include <string.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }
    const char *mode = argv[1];
    const char *input = argv[2];
    if (strlen(input) > 1023) {
        puts("USAGE");
        return 0;
    }
    if (strcmp(mode, "escape") == 0) {
        char out[2048]; // enough for worst case (every char escaped)
        size_t out_idx = 0;
        for (size_t i = 0; input[i] != '\0'; ++i) {
            unsigned char c = (unsigned char)input[i];
            if (c == '\\') {
                out[out_idx++] = '\\';
                out[out_idx++] = '\\';
            } else if (c == '"') {
                out[out_idx++] = '\\';
                out[out_idx++] = '"';
            } else if (c == '\n') {
                out[out_idx++] = '\\';
                out[out_idx++] = 'n';
            } else if (c == '\t') {
                out[out_idx++] = '\\';
                out[out_idx++] = 't';
            } else {
                out[out_idx++] = c;
            }
        }
        out[out_idx] = '\0';
        puts(out);
        return 0;
    } else if (strcmp(mode, "unescape") == 0) {
        char out[1024]; // original length limit
        size_t out_idx = 0;
        for (size_t i = 0; input[i] != '\0'; ) {
            if (input[i] == '\\') {
                if (input[i+1] == '\0') {
                    puts("INVALID");
                    return 0;
                }
                char nxt = input[i+1];
                if (nxt == '\\') {
                    out[out_idx++] = '\\';
                } else if (nxt == '"') {
                    out[out_idx++] = '"';
                } else if (nxt == 'n') {
                    out[out_idx++] = '\n';
                } else if (nxt == 't') {
                    out[out_idx++] = '\t';
                } else {
                    puts("INVALID");
                    return 0;
                }
                i += 2;
            } else {
                out[out_idx++] = input[i++];
            }
        }
        out[out_idx] = '\0';
        puts(out);
        return 0;
    } else {
        puts("INVALID_MODE");
        return 0;
    }
}
